class AssistantTests(unittest.TestCase):
    """隔离外部服务，验证业务状态只在操作成功时更新。"""

    def setUp(self):
        """为每个用例创建独立工具、环境配置和临时文件目录。"""
        self.directory = tempfile.TemporaryDirectory()
        self.addCleanup(self.directory.cleanup)
        self.root = Path(self.directory.name)
        self.memory = MagicMock()
        self.memory.run.return_value = "✅ 已保存"
        self.memory.memory_manager.memory_types = {}
        self.rag = MagicMock(initialized=True)
        self.rag._pipelines = {"pdf_alice": {"store": MagicMock(), "search": MagicMock()}}
        for patcher in (
            patch.dict(os.environ, {
                "MODELSCOPE_BASE_URL": "https://modelscope.example/v1",
                "MODELSCOPE_API_KEY": "test-modelscope-key",
                "MODELSCOPE_MODEL_ID": "test-model",
                "LLM_BASE_URL": "https://other.example/v1",
                "LLM_API_KEY": "test-other-key",
            }),
            patch.object(qa, "APP_DIR", self.root),
            patch.object(qa, "MemoryTool", return_value=self.memory),
            patch.object(qa, "RAGTool", return_value=self.rag),
            patch.object(qa, "HelloAgentsLLM", return_value=MagicMock()),
        ):
            patcher.start()
            self.addCleanup(patcher.stop)
        self.assistant = qa.PDFLearningAssistant("alice")
        self.pdf = self.root / "lesson.pdf"
        self.pdf.write_bytes(b"%PDF-1.4\n")

    def _use_real_rag(self):
        """使用真实 RAG 调用分发和错误处理，保留隔离的向量存储。"""
        rag = RAGTool.__new__(RAGTool)
        rag.initialized = True
        rag.rag_namespace = self.assistant.namespace
        rag._pipelines = self.rag._pipelines
        self.assistant.rag_tool = rag
        store = rag._pipelines[self.assistant.namespace]["store"]
        store.vector_size = 3
        store.add_vectors.return_value = True
        return store

    def test_pdf_94_chunks_use_ten_item_batches_and_matching_metadata(self):
        """复现 94 个文本块：NumPy 向量列表应完整写入，且每批不超过十条。"""
        store = self._use_real_rag()
        chunks = [{"id": str(index), "content": f"第 {index} 块文档内容"} for index in range(94)]
        embedder = MagicMock()
        embedder.encode.side_effect = lambda batch: [np.array([1.0, 2.0, 3.0]) for _ in batch]
        with patch.object(qa, "load_and_chunk_texts", return_value=chunks) as loader, \
             patch.object(qa, "get_text_embedder", return_value=embedder), \
             contextlib.redirect_stdout(io.StringIO()):
            result = self.assistant.load_document(str(self.pdf))
        self.assertTrue(result["success"], result)
        self.assertEqual([len(call.args[0]) for call in embedder.encode.call_args_list], [10] * 9 + [4])
        saved = store.add_vectors.call_args.kwargs
        self.assertEqual(len(saved["vectors"]), 94)
        self.assertEqual(len(saved["metadata"]), 94)
        self.assertEqual(saved["ids"], [chunk["id"] for chunk in chunks])
        self.assertEqual(saved["vectors"][0], [1.0, 2.0, 3.0])
        self.assertTrue(all(meta["rag_namespace"] == "pdf_alice" for meta in saved["metadata"]))
        self.assertEqual(loader.call_args.kwargs["namespace"], "pdf_alice")

    def test_embedding_accepts_matrix_and_single_vector(self):
        """二维批量数组和最后单条的一维数组均保留正确的向量数量。"""
        store = self._use_real_rag()
        chunks = [{"id": str(index), "content": "文档内容"} for index in range(11)]
        embedder = MagicMock()
        embedder.encode.side_effect = [np.ones((10, 3)), np.array([1.0, 2.0, 3.0])]
        with patch.object(qa, "load_and_chunk_texts", return_value=chunks), \
             patch.object(qa, "get_text_embedder", return_value=embedder), \
             contextlib.redirect_stdout(io.StringIO()):
            self.assertTrue(self.assistant.load_document(str(self.pdf))["success"])
        self.assertEqual(len(store.add_vectors.call_args.kwargs["vectors"]), 11)

    def test_invalid_embeddings_are_rejected_without_writing(self):
        """数量、维度、零向量及非有限值异常必须返回失败，不能伪装成导入成功。"""
        store = self._use_real_rag()
        chunks = [{"id": str(index), "content": "文档内容"} for index in range(2)]
        embedder = MagicMock()
        invalid_results = [np.ones((1, 3)), np.ones((2, 4)), np.zeros((2, 3)), np.full((2, 3), np.nan)]
        for embeddings in invalid_results:
            with self.subTest(shape=embeddings.shape, sample=embeddings[0, 0]):
                embedder.encode.return_value = embeddings
                with patch.object(qa, "load_and_chunk_texts", return_value=chunks), \
                     patch.object(qa, "get_text_embedder", return_value=embedder), \
                     contextlib.redirect_stdout(io.StringIO()):
                    result = self.assistant.load_document(str(self.pdf))
                self.assertFalse(result["success"], result)
        store.add_vectors.assert_not_called()
        self.memory.run.assert_not_called()
        self.assertEqual(self.assistant.stats["documents_loaded"], 0)

    def test_later_batch_failure_does_not_write_partial_document(self):
        """第二批请求失败时，第一批向量也不能提前入库或被替换为零向量。"""
        store = self._use_real_rag()
        chunks = [{"id": str(index), "content": "文档内容"} for index in range(11)]
        embedder = MagicMock()
        embedder.encode.side_effect = [np.ones((10, 3)), RuntimeError("Embedding API 400")]
        with patch.object(qa, "load_and_chunk_texts", return_value=chunks), \
             patch.object(qa, "get_text_embedder", return_value=embedder), \
             contextlib.redirect_stdout(io.StringIO()):
            result = self.assistant.load_document(str(self.pdf))
        self.assertFalse(result["success"])
        self.assertIn("Embedding API 400", result["message"])
        store.add_vectors.assert_not_called()
        self.memory.run.assert_not_called()

    def test_vector_store_failure_does_not_mark_document_loaded(self):
        """向量存储返回失败时，界面和统计必须保持未加载状态。"""
        store = self._use_real_rag()
