    def test_questions_save_full_answers_only_after_success(self):
        """问答记忆应包含实际答案，失败请求不能增加成功问答计数。"""
        self.assistant.current_document = "lesson.pdf"
        self.rag.run.return_value = "注意力机制用于计算关联权重。"
        answer = self.assistant.ask("什么是注意力机制？")
        saved = self.memory.run.call_args.args[0]
        self.assertIn(answer, saved["content"])
        self.assertIn("lesson.pdf", saved["content"])
        self.assertEqual(saved["memory_type"], "episodic")
        for failure in ("❌ 模型调用失败", "🤔 没有找到相关信息"):
            self.rag.run.return_value = failure
            self.assertEqual(self.assistant.ask("未知问题"), failure)
        self.assertEqual(self.assistant.stats["questions_asked"], 1)

