    def test_ui_uses_session_assistant_and_filepath(self):
        """回调使用传入的会话实例和文件路径，聊天记录符合消息格式。"""
        demo = qa.create_gradio_ui()
        callbacks = {item.fn.__name__: item.fn for item in demo.fns.values() if item.fn}
        alice, bob = MagicMock(), MagicMock()
        alice.ask.return_value, bob.ask.return_value = "Alice的回答", "Bob的回答"
