class QdrantCompatibilityTests(unittest.TestCase):
    """使用真实本地向量库验证搜索接口适配，无需连接云端。"""

    def test_search_preserves_payload_filter(self):
        """迁移接口后仍应返回载荷，并保留用户隔离过滤条件。"""
        client = QdrantClient(":memory:")
        self.addCleanup(client.close)
        client.create_collection("test", vectors_config=models.VectorParams(size=2, distance=models.Distance.COSINE))
        client.upsert("test", points=[
            models.PointStruct(id=1, vector=[1.0, 0.0], payload={"user_id": "alice"}),
            models.PointStruct(id=2, vector=[1.0, 0.0], payload={"user_id": "bob"}),
        ])
        qa.use_query_points(SimpleNamespace(client=client))
        hits = client.search(
            collection_name="test", query_vector=[1.0, 0.0], limit=5,
            query_filter=models.Filter(must=[models.FieldCondition(key="user_id", match=models.MatchValue(value="alice"))]),
            with_payload=True, with_vectors=False,
        )
        self.assertEqual([hit.id for hit in hits], [1])
        self.assertEqual(hits[0].payload["user_id"], "alice")


